  document.addEventListener('click',event=>{let routeButton=event.target.closest('[data-route]');if(routeButton){let result=runtime.navigateTo(routeButton.dataset.route);if(!result.ok)message(ACL.t(lang(),'denied'));renderCurrentRoute();return}let projectButton=event.target.closest('[data-project]');if(projectButton){runtime.navigateTo('project',projectButton.dataset.project);renderCurrentRoute();return}let button=event.target.closest('[data-action],[data-command]');if(!button)return;let command=commandFromElement(button);if(command.action==='eye'){let input=document.querySelector('#password');if(input)input.type=input.type==='password'?'text':'password';return}if(command.action==='close'){runtime.dispatchAction({...command,operationToken:activeOperation?.operationToken});activeOperation=null;modal.innerHTML='';return}if(command.action==='delete-spec'&&activeOperation?.kind==='spec-editor'){runtime.dispatchAction({action:'close',phase:'execute',operationToken:activeOperation.operationToken});activeOperation=null;modal.innerHTML=''}let result=runtime.dispatchAction(command);if(command.action==='logout'){renderCurrentRoute();return}if(!result.ok)message(ACL.t(lang(),'denied'))});
