    if(event.target.matches('[data-scope]')){let type=event.target.dataset.scope,key=type==='worker-project'?'projectIds':(type==='client-project'||type==='client-project-single')?'clientProjectIds':'clientOrderIds',values;if(type==='client-project-single'){values=event.target.checked?[event.target.value]:[]}else{values=activeOperation.draft[key].slice();let index=values.indexOf(event.target.value);if(event.target.checked&&index<0)values.push(event.target.value);if(!event.target.checked&&index>=0)values.splice(index,1)}let result=draftEvent({type:type==='client-project-single'?'client-project':type,key,value:values});if(result.ok)refreshAccessEditor(result.draft);return}
    if(event.target.matches('[data-project-mode]')){let result=draftEvent({type:'project-mode',value:event.target.value});if(result.ok)refreshAccessEditor(result.draft);return}
