    if(event.target.matches('[data-role-select]')){runtime.dispatchAction({action:'request-role-change',phase:'execute',operationToken:activeOperation.operationToken,payload:{role:event.target.value}});let result=runtime.dispatchAction({action:'confirm-role-change',phase:'execute',operationToken:activeOperation.operationToken});if(result.ok)refreshAccessEditor(result.draft);document.querySelectorAll('.client-extra-field').forEach(f=>f.hidden=event.target.value!=='Client');document.querySelectorAll('.worker-extra-field').forEach(f=>f.hidden=event.target.value!=='Worker');return}
