  function campoRevision(name,etiqueta,tipo,valor){
    const v=escape(valor??'');
    if(tipo==='area')return `<label class="field full"><span>${etiqueta}</span><textarea name="${name}" rows="3" translate="no">${v}</textarea></label>`;
    if(tipo==='rubro')return `<label class="field"><span>${etiqueta}</span><select name="${name}"><option value="">—</option>${specRubroOptions(valor||'')}</select></label>`;
    if(tipo==='proveedor')return `<label class="field"><span>${etiqueta}</span><select name="${name}" translate="no"><option value="">—</option>${supplierOptionsFor(valor||'')}</select></label>`;
    if(tipo==='moneda')return `<label class="field"><span>${etiqueta}</span><select name="${name}">${currencyOptions(valor||'S/')}</select></label>`;
    return `<label class="field"><span>${etiqueta}</span><input name="${name}" type="${tipo==='number'?'number':'text'}"${tipo==='number'?' step="0.01"':''} value="${v}" translate="no"></label>`;
  }
