  function revisionFieldLabel(field){const map={supplier:[ 'Proveedor','Supplier'],source:['Fuente','Source'],date:['Fecha','Date'],deliveryDate:['Fecha de entrega','Delivery date'],incoterm:['Incoterm','Incoterm'],shippingInstructions:['Instrucciones de envío','Shipping instructions'],destination:['Destino final','Final destination'],terms:['Términos de pago','Payment terms'],productionTime:['Tiempo de producción','Production time'],warranty:['Garantía','Warranty'],sideMark:['Marca lateral','Side mark'],paymentTerms:['Términos de pago','Payment terms'],shipTo:['Dirección de entrega','Delivery address'],billTo:['Dirección fiscal','Fiscal address'],supplierAddress:['Dirección del proveedor','Supplier address'],projectContact:['Contacto del proyecto','Project contact'],ocRubro:['Rubro / área','Category / area'],specifiedBy:['Especificado por','Specified by'],preparedBy:['Preparado por','Prepared by'],freight:['Flete','Freight'],freightCurrency:['Moneda del flete','Freight currency'],taxType:['Tipo de impuesto','Tax type'],taxRate:['Porcentaje del impuesto','Tax rate'],cifLabel:['Título del valor','Value title'],cifValue:['Valor CIF','CIF value'],amountCurrency:['Moneda','Currency'],contactName:['Contacto','Contact'],contactPhone:['Teléfono de contacto','Contact phone'],contactEmail:['Correo de contacto','Contact email'],adjustments:['Descuentos o recargos','Discounts or surcharges']};let pair=map[field]||[...CAMPOS_REVISION.spec,...CAMPOS_REVISION.invoice].find(([name])=>name===field)?.[1];return pair?es(pair[0],pair[1]):field}
  function revisionChangeText(change){const parts={description:es('descripción','description'),quantity:es('cantidad','quantity'),unitCost:es('costo unitario','unit cost'),currency:es('moneda','currency')};if(change.field==='item'){let donde=es('Item','Item')+' '+(Number(change.index||0)+1);if(change.part==='added')return donde+': '+es('agregado','added')+' — '+change.to;if(change.part==='removed')return donde+': '+es('eliminado','removed')+' — '+change.from;return donde+' · '+(parts[change.part]||change.part)+': '+(change.from||'—')+' → '+(change.to||'—')}return revisionFieldLabel(change.field)+': '+(change.from||'—')+' → '+(change.to||'—')}
  function revisionStampLocal(value){let d=new Date(value);return Number.isNaN(d.getTime())?String(value||''):d.toLocaleString(lang()==='es'?'es-PE':'en-GB',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})}
  function revisionSpecOptions(selected,excluirOrdenId){return currentState().state.specs.filter(s=>s.id===selected||saldoDelSpec(s,excluirOrdenId)>0).map(s=>`<option value="${escape(s.id)}" data-name="${escape(s.name)}"${s.id===selected?' selected':''}>${escape(s.name)}${s.code?' ('+escape(s.code)+')':''}</option>`).join('')}
