  // Lista en vivo los cambios que lleva el formulario, cada uno con su motivo.
  // El calculo es el mismo del motor, asi lo que se ve es lo que se guarda.
  function activarMotivos(form,tipo,actual,construir){
    let caja=form.querySelector('.rev-reasons-list');if(!caja)return;
    const pintar=()=>{
      let lista=[];try{lista=VAAKRuntime.revisionChanges(tipo,actual,construir())||[]}catch{lista=[]}
      let firma=lista.map(c=>VAAKRuntime.revisionChangeKey(c)+'|'+revisionChangeText(c)).join('\n');
      if(caja.dataset.firma===firma)return;caja.dataset.firma=firma;
      let previos={};caja.querySelectorAll('[data-reason-key]').forEach(el=>{previos[el.dataset.reasonKey]=el.value});
      caja.innerHTML=lista.length?lista.map(c=>{let k=VAAKRuntime.revisionChangeKey(c);return `<label class="rev-reason-row"><span>${escape(revisionChangeText(c))}</span><input data-reason-key="${escape(k)}" maxlength="300" translate="no" placeholder="${es('Motivo de este cambio','Reason for this change')}" value="${escape(previos[k]||'')}"></label>`}).join(''):`<p class="rev-reasons-empty">${es('Cuando modifiques un dato, aquí aparecerá ese cambio para que escribas su motivo.','When you change something, it will appear here so you can write its reason.')}</p>`};
    let espera;const programar=()=>{clearTimeout(espera);espera=setTimeout(pintar,120)};
    const fuera=event=>!event.target.closest?.('.rev-reasons-list');
    form.addEventListener('input',event=>{if(fuera(event))programar()});
    form.addEventListener('change',event=>{if(fuera(event))programar()});
    form.addEventListener('click',event=>{if(fuera(event))programar()});
    pintar();setTimeout(pintar,60)}
  function recogerMotivos(form){let reasons={},faltan=0,total=0;form.querySelectorAll('[data-reason-key]').forEach(el=>{total++;let texto=el.value.trim();el.classList.toggle('rev-reason-missing',!texto);if(texto)reasons[el.dataset.reasonKey]=texto;else faltan++});return {reasons,faltan,total}}
  function avisoMotivos(aviso,motivos){if(!motivos.total){aviso.hidden=false;aviso.textContent=es('No has modificado ningún dato.','You have not changed anything.');return true}if(motivos.faltan){aviso.hidden=false;aviso.textContent=es(`Escribe el motivo de cada cambio (falta${motivos.faltan>1?'n':''} ${motivos.faltan}).`,`Write the reason for each change (${motivos.faltan} missing).`);return true}return false}
  // Status del documento: su ultima version, quien la hizo y cuando.
  function estadoDocumento(rec){let revs=Array.isArray(rec?.revisions)?rec.revisions:[],ultima=revs[revs.length-1],partes;
    if(ultima)partes=['Rev. '+ultima.version,ultima.userName,ultima.at?revisionStampLocal(ultima.at):''];
    else partes=[es('Original','Original'),rec?.createdByName||rec?.issuedBy||'',rec?.createdAt?revisionStampLocal(rec.createdAt):''];
    return partes.filter(Boolean).join(' · ')}
  function statusDocumentoMarkup(rec){return `<small class="doc-status" translate="no"><b>Status:</b> ${escape(estadoDocumento(rec))}</small>`}
  // Arma lo que se envia al guardar una revision de OC (solo lo que cambio).
  function payloadRevisionOrden(form){let data=Object.fromEntries(new FormData(form).entries());let items=[];form.querySelectorAll('.rev-item').forEach(row=>{let i=row.dataset.itemIndex,sel=row.querySelector(`[name="itemSpec${i}"]`),opt=sel?.selectedOptions[0],original={};try{original=JSON.parse(row.dataset.original||'{}')}catch{original={}}let elegido=sel?.value||'';if(!elegido&&!original.description&&!original.specId)return;items.push({...original,specId:elegido||original.specId||'',description:elegido&&elegido!==original.specId?(opt?.dataset.name||original.description||''):(original.description||opt?.dataset.name||''),quantity:Number(data[`itemQuantity${i}`]||0),currency:data[`itemCurrency${i}`]||original.currency||'S/',unitCost:Number(data[`itemCost${i}`]||0)})});let baseline={};try{baseline=JSON.parse(form.dataset.baseline||'{}')}catch{baseline={}}let payload={items,adjustments:collectOrderAdjustments(form,data)};Object.keys(data).forEach(key=>{if(/^(item|adj)[A-Z]/.test(key)||key==='reason')return;if(String(data[key]??'')!==String(baseline[key]??''))payload[key]=data[key]});return payload}
  // Los cuadros de texto largo crecen hacia abajo con su contenido.
  function crecerTexto(area){if(!area)return;area.style.height='auto';area.style.height=area.scrollHeight+2+'px'}
  document.addEventListener('input',event=>{if(event.target.matches?.('textarea.auto-grow'))crecerTexto(event.target)});
  new MutationObserver(()=>modal.querySelectorAll('textarea.auto-grow').forEach(area=>{if(!area.dataset.crecido){area.dataset.crecido='1';requestAnimationFrame(()=>crecerTexto(area))}})).observe(modal,{childList:true,subtree:true});
  // Tarjeta de spec. Arriba: codigo, nombre y status. Al medio: datos.
